pragma solidity ^0.8.20;

import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

/**
 * @title TicTacToe
 * @notice A gas-optimized, secure, non-custodial PvP Tic Tac Toe game with wagering.
 * @author Senior Product Engineer
 * @dev Implements strict Checks-Effects-Interactions pattern, Pull-over-Push payments,
 *      and storage packing for gas efficiency.
 */
contract TicTacToe is ReentrancyGuard {
    // ═══════════════════════════════════════════════════════════════
    // ERRORS
    // ═══════════════════════════════════════════════════════════════

    error InvalidStake();
    error InvalidMove(uint8 col, uint8 row);
    error GameNotJoinable();
    error GameNotActive();
    error NotAuthorized();
    error NotYourTurn();
    error CellOccupied();
    error TimeoutNotReached();
    error NoFundsToWithdraw();
    error TransferFailed();
    error GameAlreadyFinished();

    // ═══════════════════════════════════════════════════════════════
    // EVENTS
    // ═══════════════════════════════════════════════════════════════

    event GameCreated(uint256 indexed gameId, address indexed creator, uint256 stake);
    event GameJoined(uint256 indexed gameId, address indexed player2);
    event MoveMade(uint256 indexed gameId, address indexed player, uint8 col, uint8 row, uint8 mark);
    event GameFinished(uint256 indexed gameId, address indexed winner, uint256 prize);
    event GameDraw(uint256 indexed gameId);
    event GameCancelled(uint256 indexed gameId, address indexed creator);
    event Withdrawal(address indexed player, uint256 amount);

    // ═══════════════════════════════════════════════════════════════
    // CONSTANTS & STATE
    // ═══════════════════════════════════════════════════════════════

    uint32 public constant ACTION_TIMEOUT = 1 hours;
    uint8 private constant STATE_WAITING = 0;
    uint8 private constant STATE_ACTIVE = 1;
    uint8 private constant STATE_FINISHED = 2;

    // Win patterns (packed bitmasks for 3x3 grid)
    // Board indices: 0 1 2 / 3 4 5 / 6 7 8
    // Representation: 2 bits per cell in uint32.
    // We check logic dynamically to save code size vs complex bitmask arrays.

    struct Game {
        // Slot 0
        address player1;      // 20 bytes
        uint96 stake;         // 12 bytes (max ~79 billion ETH)

        // Slot 1
        address player2;      // 20 bytes
        uint32 lastActionTime;// 4 bytes
        uint32 board;         // 4 bytes (18 bits used)
        uint8 movesMade;      // 1 byte
        uint8 turn;           // 1 byte (1=P1, 2=P2)
        uint8 state;          // 1 byte
        // Total: 31 bytes (Packed tightly)
    }

    mapping(uint256 => Game) public games;
    mapping(address => uint256) public pendingWithdrawals;
    uint256 public nextGameId;

    // ═══════════════════════════════════════════════════════════════
    // CONSTRUCTOR
    // ═══════════════════════════════════════════════════════════════

    constructor() {
        // Starts game IDs from 1 for safer checks
        nextGameId = 1;
    }

    // ═══════════════════════════════════════════════════════════════
    // EXTERNAL FUNCTIONS
    // ═══════════════════════════════════════════════════════════════

    /**
     * @notice Create a new game with a wager
     * @return gameId The ID of the created game
     */
    function createGame() external payable returns (uint256 gameId) {
        // CEI: Checks
        if (msg.value == 0) revert InvalidStake();

        // Effects
        unchecked {
            gameId = nextGameId++;
        }

        games[gameId] = Game({
            player1: msg.sender,
            stake: uint96(msg.value),
            player2: address(0),
            lastActionTime: uint32(block.timestamp),
            board: 0,
            movesMade: 0,
            turn: 1, // Player 1 starts
            state: STATE_WAITING
        });

        emit GameCreated(gameId, msg.sender, msg.value);
    }

    /**
     * @notice Join an existing game
     * @param gameId The ID of the game to join
     */
    function joinGame(uint256 gameId) external payable {
        Game storage g = games[gameId];

        // Checks
        if (g.state != STATE_WAITING) revert GameNotJoinable();
        if (msg.value != uint256(g.stake)) revert InvalidStake();
        if (g.player1 == msg.sender) revert NotAuthorized(); // Cannot play against self

        // Effects
        g.player2 = msg.sender;
        g.state = STATE_ACTIVE;
        g.lastActionTime = uint32(block.timestamp);

        emit GameJoined(gameId, msg.sender);
    }

    /**
     * @notice Cancel a waiting game and retrieve stake
     * @param gameId The ID of the game to cancel
     */
    function cancelGame(uint256 gameId) external nonReentrant {
        Game storage g = games[gameId];

        // Checks
        if (g.state != STATE_WAITING) revert GameNotJoinable();
        if (g.player1 != msg.sender) revert NotAuthorized();

        // Effects
        g.state = STATE_FINISHED;
        uint256 refund = uint256(g.stake);

        // Internal credit (Pull-over-Push)
        pendingWithdrawals[msg.sender] += refund;

        emit GameCancelled(gameId, msg.sender);
    }

    /**
     * @notice Make a move on the board
     * @param gameId The ID of the game
     * @param col The column (0-2)
     * @param row The row (0-2)
     */
    function makeMove(uint256 gameId, uint8 col, uint8 row) external {
        if (col > 2 || row > 2) revert InvalidMove(col, row);

        Game storage g = games[gameId];

        // Checks
        if (g.state != STATE_ACTIVE) revert GameNotActive();

        address currentMover = g.turn == 1 ? g.player1 : g.player2;
        if (msg.sender != currentMover) revert NotYourTurn();

        // Calculate cell index (0-8)
        uint8 cellIndex;
        unchecked { cellIndex = row * 3 + col; }

        // Check if cell is empty (2 bits per cell)
        // Shift amount: cellIndex * 2
        // Mask: 3 (binary 11) shifted
        uint32 currentBoard = g.board;
        if ((currentBoard >> (cellIndex * 2)) & 3 != 0) revert CellOccupied();

        // Effects: Update Board
        // Mark: 1 for P1, 2 for P2
        uint8 mark = g.turn;
        g.board = currentBoard | (uint32(mark) << (cellIndex * 2));
        g.movesMade++;
        g.lastActionTime = uint32(block.timestamp);

        emit MoveMade(gameId, msg.sender, col, row, mark);

        // Check Win/Draw
        if (_checkWin(g.board, mark)) {
            _finishGame(gameId, g, msg.sender);
        } else if (g.movesMade == 9) {
            _drawGame(gameId, g);
        } else {
            // Switch turn
            g.turn = g.turn == 1 ? 2 : 1;
        }
    }

    /**
     * @notice Claim victory if opponent timed out
     * @param gameId The ID of the game
     */
    function claimTimeout(uint256 gameId) external {
        Game storage g = games[gameId];

        if (g.state != STATE_ACTIVE) revert GameNotActive();
        if (block.timestamp < g.lastActionTime + ACTION_TIMEOUT) revert TimeoutNotReached();

        // Determine who timed out
        // If turn == 1, P1 timed out, P2 wins.
        // If turn == 2, P2 timed out, P1 wins.
        address winner = g.turn == 1 ? g.player2 : g.player1;

        // Anyone can trigger the timeout, but funds go to the winner
        // This prevents a user from holding funds hostage by going offline
        _finishGame(gameId, g, winner);
    }

    /**
     * @notice Withdraw accumulated funds
     */
    function withdraw() external nonReentrant {
        uint256 amount = pendingWithdrawals[msg.sender];
        if (amount == 0) revert NoFundsToWithdraw();

        // CEI: Effects before Interactions
        pendingWithdrawals[msg.sender] = 0;

        (bool success, ) = payable(msg.sender).call{value: amount}("");
        if (!success) revert TransferFailed();

        emit Withdrawal(msg.sender, amount);
    }

    // ═══════════════════════════════════════════════════════════════
    // PUBLIC VIEW FUNCTIONS
    // ═══════════════════════════════════════════════════════════════

    /**
     * @notice Get the board state as an array
     * @param gameId The ID of the game
     * @return grid 9-element array (0=empty, 1=P1, 2=P2)
     */
    function getBoard(uint256 gameId) external view returns (uint8[9] memory grid) {
        uint32 packed = games[gameId].board;
        // Unchecked safe for bounded loop
        unchecked {
            for (uint256 i = 0; i < 9; ++i) {
                grid[i] = uint8((packed >> (i * 2)) & 3);
            }
        }
    }

    // ═══════════════════════════════════════════════════════════════
    // INTERNAL FUNCTIONS
    // ═══════════════════════════════════════════════════════════════

    /**
     * @dev Finish game and credit winner
     */
    function _finishGame(uint256 gameId, Game storage g, address winner) internal {
        g.state = STATE_FINISHED;

        uint256 totalPrize;
        unchecked { totalPrize = uint256(g.stake) * 2; }

        // PULL Payment: Credit internal balance
        pendingWithdrawals[winner] += totalPrize;

        emit GameFinished(gameId, winner, totalPrize);
    }

    /**
     * @dev Finish game as draw and refund both
     */
    function _drawGame(uint256 gameId, Game storage g) internal {
        g.state = STATE_FINISHED;

        uint256 stake = uint256(g.stake);

        // PULL Payment: Credit both
        pendingWithdrawals[g.player1] += stake;
        pendingWithdrawals[g.player2] += stake;

        emit GameDraw(gameId);
    }

    /**
     * @dev Check 8 win conditions using bitwise logic
     * @param board The packed board state
     * @param player The player mark (1 or 2)
     */
    function _checkWin(uint32 board, uint8 player) internal pure returns (bool) {
        // Construct the 3 bits representing the player's potential line
        // We verify lines by checking if specific cells equal `player`

        // Indices:
        // 0 1 2
        // 3 4 5
        // 6 7 8

        // Helper to extract cell value: (board >> (i*2)) & 3

        // Hardcoded checks are most gas efficient for small N

        // Rows
        if (_checkLine(board, 0, 1, 2, player)) return true;
        if (_checkLine(board, 3, 4, 5, player)) return true;
        if (_checkLine(board, 6, 7, 8, player)) return true;

        // Cols
        if (_checkLine(board, 0, 3, 6, player)) return true;
        if (_checkLine(board, 1, 4, 7, player)) return true;
        if (_checkLine(board, 2, 5, 8, player)) return true;

        // Diagonals
        if (_checkLine(board, 0, 4, 8, player)) return true;
        if (_checkLine(board, 2, 4, 6, player)) return true;

        return false;
    }

    function _checkLine(uint32 board, uint8 c1, uint8 c2, uint8 c3, uint8 p) private pure returns (bool) {
        // Extract values using bitwise ops
        // p is 1 or 2 (binary 01 or 10)
        // If all 3 cells match p, we return true

        // Shift logic: cell * 2
        // We can do this without branching
        return (((board >> (c1 * 2)) & 3) == p) &&
               (((board >> (c2 * 2)) & 3) == p) &&
               (((board >> (c3 * 2)) & 3) == p);
    }
}
